# find windows where test object mask all zeros, rotations/reflections
mask={(0,0),(0,1),(0,2),(1,2),(2,1),(2,2)}
def transforms(S):
 out=set()
 for flip in (False,True):
  for k in range(4):
   pts=[]
   for r,c in S:
    if flip:c=-c
    for _ in range(k):r,c=c,-r
    pts.append((r,c))
   mr=min(r for r,c in pts);mc=min(c for r,c in pts)
   out.add(frozenset((r-mr,c-mc) for r,c in pts))
 return out
marks=set()
for S in transforms(mask):
 h=max(r for r,c in S)+1;w=max(c for r,c in S)+1
 for r in range(16-h+1):
  for c in range(25-w+1):
   if all(a[r+dr][c+dc]==0 for dr,dc in S): marks.update((r+dr,c+dc) for dr,dc in S)
print(len(marks), sorted(marks))

